update public.lessons l
   set homework = $j$[{"id":"w1","type":"written","warmup":true,"question":{"en":"Warm-up: using the drawing, find $(A \\cap B) \\setminus C$ and $(A \\cup B) \\setminus C$.","am":"ማሟሟቂያ፦ ሥዕሉን በመጠቀም $(A \\cap B) \\setminus C$ እና $(A \\cup B) \\setminus C$ን ፈልጉ።"},"tip":{"en":"First write A, B and C as sets of region numbers from the drawing.","am":"መጀመሪያ A፣ B እና Cን ከሥዕሉ በክፍል ቁጥሮች እንደ ስብስብ ጻፉ።"},"hints":[{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$.","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$."},{"en":"Work out the inside bracket first, then the outside operation.","am":"መጀመሪያ በቅንፉ ውስጥ ያለውን ሥሩ፣ ከዚያ የውጩን ሥራ።"}],"figure":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"caption":{"en":"The drawing from class: each region has a number. Tap a region to see its number.","am":"ከክፍል የተሰጠው ሥዕል፦ እያንዳንዱ ክፍል ቁጥር አለው። ቁጥሩን ለማየት ክፍሉን ንኩ።"}},"answers":[{"label":{"en":"$(A \\cap B) \\setminus C$","am":"$(A \\cap B) \\setminus C$"},"spec":{"kind":"set","value":["5"]}},{"label":{"en":"$(A \\cup B) \\setminus C$","am":"$(A \\cup B) \\setminus C$"},"spec":{"kind":"set","value":["1","2","5"]}}],"solution":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"steps":[{"text":{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$"},"why":{"en":"Read each circle from the drawing: write every region number inside it.","am":"እያንዳንዱን ክበብ ከሥዕሉ አንብቡ፦ በውስጡ ያሉትን የክፍል ቁጥሮች በሙሉ ጻፉ።"}},{"text":{"en":"$A \\cap B = \\{5, 7\\}$","am":"$A \\cap B = \\{5, 7\\}$"},"why":{"en":"Numbers in BOTH A and B.","am":"በA እና በB ሁለቱም ያሉ ቁጥሮች።"},"shade":"A∩B"},{"text":{"en":"$(A \\cap B) \\setminus C = \\{5\\}$","am":"$(A \\cap B) \\setminus C = \\{5\\}$"},"why":{"en":"Remove the numbers that are also in C (7).","am":"በC ውስጥም ያሉትን ቁጥሮች (7) አስወግዱ።"},"shade":"(A∩B)∖C"},{"text":{"en":"$A \\cup B = \\{1, 2, 4, 5, 6, 7\\}$","am":"$A \\cup B = \\{1, 2, 4, 5, 6, 7\\}$"},"why":{"en":"Numbers in A OR B.","am":"በA ወይም በB ያሉ ቁጥሮች።"},"shade":"A∪B"},{"text":{"en":"$(A \\cup B) \\setminus C = \\{1, 2, 5\\}$","am":"$(A \\cup B) \\setminus C = \\{1, 2, 5\\}$"},"why":{"en":"Remove 4, 6 and 7, which are in C.","am":"በC ውስጥ ያሉትን 4፣ 6 እና 7 አስወግዱ።"},"shade":"(A∪B)∖C"}],"answer":{"en":"$(A \\cap B) \\setminus C = \\{5\\}$, $(A \\cup B) \\setminus C = \\{1, 2, 5\\}$","am":"$(A \\cap B) \\setminus C = \\{5\\}$, $(A \\cup B) \\setminus C = \\{1, 2, 5\\}$"}}},{"id":"h1","type":"written","question":{"en":"Using the numbered drawing, show that $A \\cup (B \\cap C) = (A \\cup B) \\cap (A \\cup C)$. Find each side as a set of region numbers.","am":"በቁጥር የተሰየመውን ሥዕል በመጠቀም $A \\cup (B \\cap C) = (A \\cup B) \\cap (A \\cup C)$ መሆኑን አሳዩ። እያንዳንዱን ጎን በክፍል ቁጥሮች ስብስብ ፈልጉ።"},"tip":{"en":"First write A, B and C as sets of region numbers from the drawing.","am":"መጀመሪያ A፣ B እና Cን ከሥዕሉ በክፍል ቁጥሮች እንደ ስብስብ ጻፉ።"},"hints":[{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$.","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$."},{"en":"Work out the inside bracket first, then the outside operation.","am":"መጀመሪያ በቅንፉ ውስጥ ያለውን ሥሩ፣ ከዚያ የውጩን ሥራ።"}],"figure":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"caption":{"en":"The drawing from class: each region has a number. Tap a region to see its number.","am":"ከክፍል የተሰጠው ሥዕል፦ እያንዳንዱ ክፍል ቁጥር አለው። ቁጥሩን ለማየት ክፍሉን ንኩ።"}},"compare":[{"label":{"en":"Left side: $A \\cup (B \\cap C)$","am":"ግራ ጎን፦ $A \\cup (B \\cap C)$"},"shade":"A∪(B∩C)"},{"label":{"en":"Right side: $(A \\cup B) \\cap (A \\cup C)$","am":"ቀኝ ጎን፦ $(A \\cup B) \\cap (A \\cup C)$"},"shade":"(A∪B)∩(A∪C)"}],"answers":[{"label":{"en":"$B \\cap C$","am":"$B \\cap C$"},"group":{"en":"Left side","am":"ግራ ጎን"},"spec":{"kind":"set","value":["6","7"]}},{"label":{"en":"$A \\cup (B \\cap C)$","am":"$A \\cup (B \\cap C)$"},"group":{"en":"Left side","am":"ግራ ጎን"},"spec":{"kind":"set","value":["1","4","5","6","7"]}},{"label":{"en":"$A \\cup B$","am":"$A \\cup B$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["1","2","4","5","6","7"]}},{"label":{"en":"$A \\cup C$","am":"$A \\cup C$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["1","3","4","5","6","7"]}},{"label":{"en":"$(A \\cup B) \\cap (A \\cup C)$","am":"$(A \\cup B) \\cap (A \\cup C)$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["1","4","5","6","7"]}},{"label":{"en":"Left side = Right side?","am":"ግራ ጎን = ቀኝ ጎን?"},"group":{"en":"Conclusion","am":"መደምደሚያ"},"spec":{"kind":"choice","options":[{"en":"Equal ✓","am":"እኩል ናቸው ✓"},{"en":"Not equal ✗","am":"እኩል አይደሉም ✗"}],"correct":0}}],"solution":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"steps":[{"text":{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$"},"why":{"en":"Read each circle from the drawing: write every region number inside it.","am":"እያንዳንዱን ክበብ ከሥዕሉ አንብቡ፦ በውስጡ ያሉትን የክፍል ቁጥሮች በሙሉ ጻፉ።"}},{"text":{"en":"$B \\cap C = \\{6, 7\\}$","am":"$B \\cap C = \\{6, 7\\}$"},"why":{"en":"Left side, bracket first: numbers in both B and C.","am":"ግራ ጎን፣ መጀመሪያ ቅንፍ፦ በB እና በC ሁለቱም ያሉ ቁጥሮች።"},"shade":"B∩C"},{"text":{"en":"$A \\cup (B \\cap C) = \\{1, 4, 5, 6, 7\\}$","am":"$A \\cup (B \\cap C) = \\{1, 4, 5, 6, 7\\}$"},"why":{"en":"Add every number of A: 1, 4, 5, 7.","am":"የAን ቁጥሮች በሙሉ ጨምሩ፦ 1፣ 4፣ 5፣ 7።"},"shade":"A∪(B∩C)"},{"text":{"en":"$A \\cup B = \\{1, 2, 4, 5, 6, 7\\}$","am":"$A \\cup B = \\{1, 2, 4, 5, 6, 7\\}$"},"why":{"en":"Right side: everything in A or B.","am":"ቀኝ ጎን፦ በA ወይም በB ያለ ሁሉ።"},"shade":"A∪B"},{"text":{"en":"$A \\cup C = \\{1, 3, 4, 5, 6, 7\\}$","am":"$A \\cup C = \\{1, 3, 4, 5, 6, 7\\}$"},"why":{"en":"Everything in A or C.","am":"በA ወይም በC ያለ ሁሉ።"},"shade":"A∪C"},{"text":{"en":"$(A \\cup B) \\cap (A \\cup C) = \\{1, 4, 5, 6, 7\\}$","am":"$(A \\cup B) \\cap (A \\cup C) = \\{1, 4, 5, 6, 7\\}$"},"why":{"en":"Keep the numbers that are in BOTH lists.","am":"በሁለቱም ዝርዝሮች ያሉትን ቁጥሮች ያዙ።"},"shade":"(A∪B)∩(A∪C)"},{"text":{"en":"Both sides are $\\{1, 4, 5, 6, 7\\}$, so they are equal ✓","am":"ሁለቱም ጎኖች $\\{1, 4, 5, 6, 7\\}$ ናቸው፤ ስለዚህ እኩል ናቸው ✓"},"why":{"en":"Two sets with exactly the same elements are equal.","am":"በትክክል አንድ ዓይነት አባላት ያሏቸው ሁለት ስብስቦች እኩል ናቸው።"},"shade":"A∪(B∩C)"}],"answer":{"en":"$A \\cup (B \\cap C) = (A \\cup B) \\cap (A \\cup C) = \\{1, 4, 5, 6, 7\\}$","am":"$A \\cup (B \\cap C) = (A \\cup B) \\cap (A \\cup C) = \\{1, 4, 5, 6, 7\\}$"}}},{"id":"h2","type":"written","question":{"en":"Using the numbered drawing, show that $A - (B \\cup C) = (A - B) \\cap (A - C)$, the same as $A \\setminus (B \\cup C) = (A \\setminus B) \\cap (A \\setminus C)$. Find each side as a set of region numbers.","am":"በቁጥር የተሰየመውን ሥዕል በመጠቀም $A - (B \\cup C) = (A - B) \\cap (A - C)$ መሆኑን አሳዩ፤ ይህም $A \\setminus (B \\cup C) = (A \\setminus B) \\cap (A \\setminus C)$ ማለት ነው። እያንዳንዱን ጎን በክፍል ቁጥሮች ስብስብ ፈልጉ።"},"tip":{"en":"First write A, B and C as sets of region numbers from the drawing.","am":"መጀመሪያ A፣ B እና Cን ከሥዕሉ በክፍል ቁጥሮች እንደ ስብስብ ጻፉ።"},"hints":[{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$.","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$."},{"en":"Work out the inside bracket first, then the outside operation.","am":"መጀመሪያ በቅንፉ ውስጥ ያለውን ሥሩ፣ ከዚያ የውጩን ሥራ።"}],"figure":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"caption":{"en":"The drawing from class: each region has a number. Tap a region to see its number.","am":"ከክፍል የተሰጠው ሥዕል፦ እያንዳንዱ ክፍል ቁጥር አለው። ቁጥሩን ለማየት ክፍሉን ንኩ።"}},"compare":[{"label":{"en":"Left side: $A \\setminus (B \\cup C)$","am":"ግራ ጎን፦ $A \\setminus (B \\cup C)$"},"shade":"A∖(B∪C)"},{"label":{"en":"Right side: $(A \\setminus B) \\cap (A \\setminus C)$","am":"ቀኝ ጎን፦ $(A \\setminus B) \\cap (A \\setminus C)$"},"shade":"(A∖B)∩(A∖C)"}],"answers":[{"label":{"en":"$B \\cup C$","am":"$B \\cup C$"},"group":{"en":"Left side","am":"ግራ ጎን"},"spec":{"kind":"set","value":["2","3","4","5","6","7"]}},{"label":{"en":"$A \\setminus (B \\cup C)$","am":"$A \\setminus (B \\cup C)$"},"group":{"en":"Left side","am":"ግራ ጎን"},"spec":{"kind":"set","value":["1"]}},{"label":{"en":"$A \\setminus B$","am":"$A \\setminus B$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["1","4"]}},{"label":{"en":"$A \\setminus C$","am":"$A \\setminus C$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["1","5"]}},{"label":{"en":"$(A \\setminus B) \\cap (A \\setminus C)$","am":"$(A \\setminus B) \\cap (A \\setminus C)$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["1"]}},{"label":{"en":"Left side = Right side?","am":"ግራ ጎን = ቀኝ ጎን?"},"group":{"en":"Conclusion","am":"መደምደሚያ"},"spec":{"kind":"choice","options":[{"en":"Equal ✓","am":"እኩል ናቸው ✓"},{"en":"Not equal ✗","am":"እኩል አይደሉም ✗"}],"correct":0}}],"solution":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"steps":[{"text":{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$"},"why":{"en":"Read each circle from the drawing: write every region number inside it.","am":"እያንዳንዱን ክበብ ከሥዕሉ አንብቡ፦ በውስጡ ያሉትን የክፍል ቁጥሮች በሙሉ ጻፉ።"}},{"text":{"en":"$B \\cup C = \\{2, 3, 4, 5, 6, 7\\}$","am":"$B \\cup C = \\{2, 3, 4, 5, 6, 7\\}$"},"why":{"en":"Left side, bracket first: everything in B or C.","am":"ግራ ጎን፣ መጀመሪያ ቅንፍ፦ በB ወይም በC ያለ ሁሉ።"},"shade":"B∪C"},{"text":{"en":"$A \\setminus (B \\cup C) = \\{1\\}$","am":"$A \\setminus (B \\cup C) = \\{1\\}$"},"why":{"en":"From A = {1, 4, 5, 7} remove every number of $B \\cup C$.","am":"ከA = {1, 4, 5, 7} የ$B \\cup C$ን ቁጥሮች በሙሉ አስወግዱ።"},"shade":"A∖(B∪C)"},{"text":{"en":"$A \\setminus B = \\{1, 4\\}$","am":"$A \\setminus B = \\{1, 4\\}$"},"why":{"en":"Right side: A without 5 and 7 (they are in B).","am":"ቀኝ ጎን፦ ያለ 5 እና 7 ያለው A (በB ውስጥ ናቸው)።"},"shade":"A∖B"},{"text":{"en":"$A \\setminus C = \\{1, 5\\}$","am":"$A \\setminus C = \\{1, 5\\}$"},"why":{"en":"A without 4 and 7 (they are in C).","am":"ያለ 4 እና 7 ያለው A (በC ውስጥ ናቸው)።"},"shade":"A∖C"},{"text":{"en":"$(A \\setminus B) \\cap (A \\setminus C) = \\{1\\}$","am":"$(A \\setminus B) \\cap (A \\setminus C) = \\{1\\}$"},"why":{"en":"Only 1 is in both lists.","am":"በሁለቱም ዝርዝሮች ያለው 1 ብቻ ነው።"},"shade":"(A∖B)∩(A∖C)"},{"text":{"en":"Both sides are $\\{1\\}$, so they are equal ✓","am":"ሁለቱም ጎኖች $\\{1\\}$ ናቸው፤ ስለዚህ እኩል ናቸው ✓"},"why":{"en":"$A - B$ and $A \\setminus B$ are two ways to write the same thing.","am":"$A - B$ እና $A \\setminus B$ አንድን ነገር የሚጽፉባቸው ሁለት መንገዶች ናቸው።"},"shade":"A∖(B∪C)"}],"answer":{"en":"$A - (B \\cup C) = (A - B) \\cap (A - C) = \\{1\\}$","am":"$A - (B \\cup C) = (A - B) \\cap (A - C) = \\{1\\}$"}}},{"id":"h3","type":"written","question":{"en":"Using the numbered drawing, show that $A \\setminus B = A \\setminus (A \\cap B)$, the same as $A - B = A - (A \\cap B)$. Find each side as a set of region numbers.","am":"በቁጥር የተሰየመውን ሥዕል በመጠቀም $A \\setminus B = A \\setminus (A \\cap B)$ መሆኑን አሳዩ፤ ይህም $A - B = A - (A \\cap B)$ ማለት ነው። እያንዳንዱን ጎን በክፍል ቁጥሮች ስብስብ ፈልጉ።"},"tip":{"en":"First write A, B and C as sets of region numbers from the drawing.","am":"መጀመሪያ A፣ B እና Cን ከሥዕሉ በክፍል ቁጥሮች እንደ ስብስብ ጻፉ።"},"hints":[{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$.","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$."},{"en":"Work out the inside bracket first, then the outside operation.","am":"መጀመሪያ በቅንፉ ውስጥ ያለውን ሥሩ፣ ከዚያ የውጩን ሥራ።"}],"figure":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"caption":{"en":"The drawing from class: each region has a number. Tap a region to see its number.","am":"ከክፍል የተሰጠው ሥዕል፦ እያንዳንዱ ክፍል ቁጥር አለው። ቁጥሩን ለማየት ክፍሉን ንኩ።"}},"compare":[{"label":{"en":"Left side: $A \\setminus B$","am":"ግራ ጎን፦ $A \\setminus B$"},"shade":"A∖B"},{"label":{"en":"Right side: $A \\setminus (A \\cap B)$","am":"ቀኝ ጎን፦ $A \\setminus (A \\cap B)$"},"shade":"A∖(A∩B)"}],"answers":[{"label":{"en":"$A \\setminus B$","am":"$A \\setminus B$"},"group":{"en":"Left side","am":"ግራ ጎን"},"spec":{"kind":"set","value":["1","4"]}},{"label":{"en":"$A \\cap B$","am":"$A \\cap B$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["5","7"]}},{"label":{"en":"$A \\setminus (A \\cap B)$","am":"$A \\setminus (A \\cap B)$"},"group":{"en":"Right side","am":"ቀኝ ጎን"},"spec":{"kind":"set","value":["1","4"]}},{"label":{"en":"Left side = Right side?","am":"ግራ ጎን = ቀኝ ጎን?"},"group":{"en":"Conclusion","am":"መደምደሚያ"},"spec":{"kind":"choice","options":[{"en":"Equal ✓","am":"እኩል ናቸው ✓"},{"en":"Not equal ✗","am":"እኩል አይደሉም ✗"}],"correct":0}}],"solution":{"venn":{"sets":3,"labels":["A","B","C"],"elements":{"A":["1"],"B":["2"],"C":["3"],"AC":["4"],"AB":["5"],"BC":["6"],"ABC":["7"],"none":["8"]}},"steps":[{"text":{"en":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$","am":"$A = \\{1, 4, 5, 7\\}$, $B = \\{2, 5, 6, 7\\}$, $C = \\{3, 4, 6, 7\\}$"},"why":{"en":"Read each circle from the drawing: write every region number inside it.","am":"እያንዳንዱን ክበብ ከሥዕሉ አንብቡ፦ በውስጡ ያሉትን የክፍል ቁጥሮች በሙሉ ጻፉ።"}},{"text":{"en":"$A \\setminus B = \\{1, 4\\}$","am":"$A \\setminus B = \\{1, 4\\}$"},"why":{"en":"Left side: A without the numbers that are in B (5 and 7).","am":"ግራ ጎን፦ በB ውስጥ ያሉት ቁጥሮች (5 እና 7) የሌሉበት A።"},"shade":"A∖B"},{"text":{"en":"$A \\cap B = \\{5, 7\\}$","am":"$A \\cap B = \\{5, 7\\}$"},"why":{"en":"Right side, bracket first: numbers in both A and B.","am":"ቀኝ ጎን፣ መጀመሪያ ቅንፍ፦ በA እና በB ሁለቱም ያሉ ቁጥሮች።"},"shade":"A∩B"},{"text":{"en":"$A \\setminus (A \\cap B) = \\{1, 4\\}$","am":"$A \\setminus (A \\cap B) = \\{1, 4\\}$"},"why":{"en":"From A remove 5 and 7.","am":"ከA 5 እና 7ን አስወግዱ።"},"shade":"A∖(A∩B)"},{"text":{"en":"Both sides are $\\{1, 4\\}$, so they are equal ✓","am":"ሁለቱም ጎኖች $\\{1, 4\\}$ ናቸው፤ ስለዚህ እኩል ናቸው ✓"},"why":{"en":"Removing B from A only removes the part of B inside A, which is $A \\cap B$.","am":"Bን ከA ማስወገድ በA ውስጥ ያለውን የB ክፍል ብቻ ያስወግዳል፤ ይህም $A \\cap B$ ነው።"},"shade":"A∖B"}],"answer":{"en":"$A \\setminus B = A \\setminus (A \\cap B) = \\{1, 4\\}$","am":"$A \\setminus B = A \\setminus (A \\cap B) = \\{1, 4\\}$"}}},{"id":"h4","type":"choice","question":{"en":"Exam question: For sets A, B and C, if $A \\cup C = \\{x \\in \\mathbb{Z} \\mid -3 < x < 3\\}$ and $B \\cup C = \\{x \\in \\mathbb{R} \\mid x^3 = x\\}$, then $(A \\cap B) \\cup C$ is equal to:","am":"የፈተና ጥያቄ፦ ለስብስቦች A፣ B እና C፣ $A \\cup C = \\{x \\in \\mathbb{Z} \\mid -3 < x < 3\\}$ እና $B \\cup C = \\{x \\in \\mathbb{R} \\mid x^3 = x\\}$ ከሆኑ፣ $(A \\cap B) \\cup C$ ከምን ጋር እኩል ነው?"},"tip":{"en":"Use the distributive law: $(A \\cap B) \\cup C = (A \\cup C) \\cap (B \\cup C)$. Then you only need the two sets you are given.","am":"የማሰራጨት ሕግን ተጠቀሙ፦ $(A \\cap B) \\cup C = (A \\cup C) \\cap (B \\cup C)$። ከዚያ የተሰጡትን ሁለት ስብስቦች ብቻ ትፈልጋላችሁ።"},"hints":[{"en":"List $A \\cup C$: the integers between −3 and 3 (not including them).","am":"$A \\cup C$ን ዘርዝሩ፦ በ−3 እና በ3 መካከል ያሉ ኢንቲጀሮች (እነሱን ሳይጨምር)።"},{"en":"Solve $x^3 = x$ by factoring: $x(x - 1)(x + 1) = 0$.","am":"$x^3 = x$ን በመፍታት ፈቱ፦ $x(x - 1)(x + 1) = 0$።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","options":[{"en":"$\\{0, 1, 2\\}$","am":"$\\{0, 1, 2\\}$"},{"en":"$\\{-1, 0, 1\\}$","am":"$\\{-1, 0, 1\\}$"},{"en":"$\\{-2, -1, 0, 1, 2\\}$","am":"$\\{-2, -1, 0, 1, 2\\}$"},{"en":"$\\{0\\}$","am":"$\\{0\\}$"}],"correct":1}}],"solution":{"steps":[{"text":{"en":"$A \\cup C = \\{-2, -1, 0, 1, 2\\}$","am":"$A \\cup C = \\{-2, -1, 0, 1, 2\\}$"},"why":{"en":"Integers strictly between −3 and 3.","am":"በ−3 እና በ3 መካከል ብቻ ያሉ ኢንቲጀሮች።"}},{"text":{"en":"$x^3 = x \\Rightarrow x^3 - x = 0$","am":"$x^3 = x \\Rightarrow x^3 - x = 0$"},"why":{"en":"Move everything to one side so we can factor.","am":"ለመፍታት ሁሉንም ወደ አንድ ጎን አምጡ።"}},{"text":{"en":"$x(x^2 - 1) = 0 \\Rightarrow x(x - 1)(x + 1) = 0$","am":"$x(x^2 - 1) = 0 \\Rightarrow x(x - 1)(x + 1) = 0$"},"why":{"en":"Take out x, then $x^2 - 1$ is a difference of squares.","am":"xን አውጡ፣ ከዚያ $x^2 - 1$ የካሬዎች ልዩነት ነው።"}},{"text":{"en":"$x = 0,\\ 1,\\ -1$, so $B \\cup C = \\{-1, 0, 1\\}$","am":"$x = 0,\\ 1,\\ -1$፤ ስለዚህ $B \\cup C = \\{-1, 0, 1\\}$"},"why":{"en":"A product is 0 when one factor is 0.","am":"ብዜት 0 የሚሆነው አንዱ ተባዥ 0 ሲሆን ነው።"}},{"text":{"en":"$(A \\cap B) \\cup C = (A \\cup C) \\cap (B \\cup C)$","am":"$(A \\cap B) \\cup C = (A \\cup C) \\cap (B \\cup C)$"},"why":{"en":"Distributive law: union distributes over intersection.","am":"የማሰራጨት ሕግ፦ ውህደት በመገናኛ ላይ ይሰራጫል።"}},{"text":{"en":"$= \\{-2, -1, 0, 1, 2\\} \\cap \\{-1, 0, 1\\} = \\{-1, 0, 1\\}$","am":"$= \\{-2, -1, 0, 1, 2\\} \\cap \\{-1, 0, 1\\} = \\{-1, 0, 1\\}$"},"why":{"en":"Keep the elements that are in both sets.","am":"በሁለቱም ስብስቦች ያሉትን አባላት ያዙ።"}}],"answer":{"en":"b) $\\{-1, 0, 1\\}$","am":"ለ) $\\{-1, 0, 1\\}$"}}},{"id":"h5","type":"choice","question":{"en":"Exam question: In a group of 40 boys, 28 like football while 18 like basketball. If 3 boys like neither of the games, then the number of boys who like both games is:","am":"የፈተና ጥያቄ፦ በ40 ወንዶች ቡድን ውስጥ 28ቱ እግር ኳስ፣ 18ቱ ቅርጫት ኳስ ይወዳሉ። 3 ወንዶች ሁለቱንም ጨዋታ ካልወደዱ፣ ሁለቱንም ጨዋታ የሚወዱ ወንዶች ቁጥር ስንት ነው?"},"tip":{"en":"First find how many like at least one game, then use $n(F \\cup B) = n(F) + n(B) - n(F \\cap B)$.","am":"መጀመሪያ ቢያንስ አንዱን ጨዋታ የሚወዱትን ፈልጉ፣ ከዚያ $n(F \\cup B) = n(F) + n(B) - n(F \\cap B)$ን ተጠቀሙ።"},"hints":[{"en":"Boys who like at least one game: $40 - 3$.","am":"ቢያንስ አንዱን ጨዋታ የሚወዱ፦ $40 - 3$።"},{"en":"$37 = 28 + 18 - x$. Solve for x.","am":"$37 = 28 + 18 - x$። xን ፈልጉ።"}],"answers":[{"label":{"en":"Choose the answer","am":"መልሱን ምረጡ"},"spec":{"kind":"choice","options":[{"en":"4","am":"4"},{"en":"6","am":"6"},{"en":"9","am":"9"},{"en":"12","am":"12"}],"correct":2}}],"solution":{"venn":{"sets":2,"labels":["F","B"],"elements":{"A":["19"],"AB":["9"],"B":["9"],"none":["3"]}},"steps":[{"text":{"en":"$n(F \\cup B) = 40 - 3 = 37$","am":"$n(F \\cup B) = 40 - 3 = 37$"},"why":{"en":"Everyone except the 3 who like neither game.","am":"ሁለቱንም ከማይወዱት 3 በስተቀር ሁሉም።"},"shade":"F∪B"},{"text":{"en":"$n(F \\cup B) = n(F) + n(B) - n(F \\cap B)$","am":"$n(F \\cup B) = n(F) + n(B) - n(F \\cap B)$"},"why":{"en":"Adding F and B counts the boys in both twice, so subtract them once.","am":"Fን እና Bን መደመር በሁለቱም ያሉትን ሁለት ጊዜ ይቆጥራል፤ ስለዚህ አንድ ጊዜ ቀንሱ።"}},{"text":{"en":"$37 = 28 + 18 - x = 46 - x$","am":"$37 = 28 + 18 - x = 46 - x$"},"why":{"en":"Put in the numbers, with x = boys who like both.","am":"ቁጥሮቹን አስገቡ፤ x = ሁለቱንም የሚወዱ።"}},{"text":{"en":"$x = 46 - 37 = 9$","am":"$x = 46 - 37 = 9$"},"why":{"en":"Move x to one side.","am":"xን ወደ አንድ ጎን አምጡ።"},"shade":"F∩B"},{"text":{"en":"Check: only football $28 - 9 = 19$, both 9, only basketball $18 - 9 = 9$, neither 3. $19 + 9 + 9 + 3 = 40$ ✓","am":"ማረጋገጫ፦ እግር ኳስ ብቻ $28 - 9 = 19$፣ ሁለቱም 9፣ ቅርጫት ኳስ ብቻ $18 - 9 = 9$፣ ምንም 3። $19 + 9 + 9 + 3 = 40$ ✓"},"why":{"en":"The four regions of the Venn diagram must add up to all 40 boys.","am":"የቬን ዲያግራሙ አራቱ ክፍሎች ሁሉንም 40 ወንዶች መሆን አለባቸው።"},"shade":"U"}],"answer":{"en":"c) 9","am":"ሐ) 9"}}}]$j$::jsonb,
       updated_at = now()
 where l.slug = '1-1'
   and l.unit_id in (
         select u.id from public.units u
           join public.grades g on g.id = u.grade_id
           join public.subjects s on s.id = g.subject_id
          where s.slug = 'mathematics' and g.number = 9 and u.number = 1)
   and not exists (select 1 from public.lesson_versions v where v.lesson_id = l.id);
